import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.166.1/build/three.module.js';

// VERDANT prototype: presentation, combat, and ecosystem logic are intentionally separated.
const canvas=document.querySelector('#game');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.08;
const scene=new THREE.Scene();scene.background=new THREE.Color('#a9c2a8');scene.fog=new THREE.FogExp2('#9aaf98',.012);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,180);
scene.add(new THREE.HemisphereLight('#d9f3db','#354035',2.0));
const sun=new THREE.DirectionalLight('#fff0cf',3.3);sun.position.set(-25,40,22);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-38;sun.shadow.camera.right=38;sun.shadow.camera.top=38;sun.shadow.camera.bottom=-38;scene.add(sun);
const fill=new THREE.DirectionalLight('#94dcdd',.8);fill.position.set(18,12,-18);scene.add(fill);
const mats={ground:new THREE.MeshStandardMaterial({color:'#526f50',roughness:1}),grass:new THREE.MeshStandardMaterial({color:'#809565',roughness:1}),bark:new THREE.MeshStandardMaterial({color:'#5a4736',roughness:1}),leaf:new THREE.MeshStandardMaterial({color:'#3e6547',roughness:.92}),leaf2:new THREE.MeshStandardMaterial({color:'#668356',roughness:.95}),rock:new THREE.MeshStandardMaterial({color:'#777c6b',roughness:1}),pixel:new THREE.MeshStandardMaterial({color:'#67b4a9',roughness:.6,metalness:.12,emissive:'#14594f',emissiveIntensity:.3}),glow:new THREE.MeshBasicMaterial({color:'#a9ff82'}),monster:new THREE.MeshStandardMaterial({color:'#547e79',roughness:.55,emissive:'#1f5e56',emissiveIntensity:.55}),animal:new THREE.MeshStandardMaterial({color:'#ad9b74',roughness:.9}),steel:new THREE.MeshStandardMaterial({color:'#c6d1bc',metalness:.7,roughness:.27}),gold:new THREE.MeshStandardMaterial({color:'#dbc289',metalness:.55,roughness:.3}),cloth:new THREE.MeshStandardMaterial({color:'#314e43',roughness:.9}),skin:new THREE.MeshStandardMaterial({color:'#bd9978',roughness:.8})};
const ground=new THREE.Mesh(new THREE.PlaneGeometry(160,160),mats.ground);ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;scene.add(ground);
const meadow=new THREE.Mesh(new THREE.CircleGeometry(27,48),new THREE.MeshStandardMaterial({color:'#70875b',roughness:1}));meadow.rotation.x=-Math.PI/2;meadow.position.y=.025;scene.add(meadow);
const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function mesh(geo,mat,parent,pos=[0,0,0]){const m=new THREE.Mesh(geo,mat);m.position.set(...pos);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function tree(x,z,scale=1,voxel=false){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(scale);scene.add(g);if(voxel){mesh(new THREE.BoxGeometry(.8,2.7,.8),mats.bark,g,[0,1.3,0]);for(let i=0;i<3;i++){let b=mesh(new THREE.BoxGeometry(2.2-i*.35,1.25,2.2-i*.35),i===0?mats.pixel:mats.monster,g,[0,2.3+i*.72,0]);b.rotation.y=rand(0,1.5)}for(let i=0;i<8;i++){const b=mesh(new THREE.BoxGeometry(.34,.34,.34),mats.glow,g,[rand(-1.5,1.5),rand(1.7,4.2),rand(-1.5,1.5)]);b.material=new THREE.MeshBasicMaterial({color:i%2?'#8ef5ee':'#a9ff82',transparent:true,opacity:.75})}}else{mesh(new THREE.CylinderGeometry(.13,.25,2.5,7),mats.bark,g,[0,1.25,0]);const a=mesh(new THREE.ConeGeometry(rand(1.15,1.7),rand(2,2.7),7),mats.leaf,g,[0,2.6,0]);const b=mesh(new THREE.ConeGeometry(rand(.8,1.25),1.9,7),mats.leaf2,g,[0,3.55,0]);a.rotation.y=rand(0,4);b.rotation.y=rand(0,4)}return g;}
const organicTrees=[];for(let i=0;i<68;i++){let a=rand(0,Math.PI*2),r=rand(18,52);organicTrees.push(tree(Math.cos(a)*r,Math.sin(a)*r,rand(.7,1.5)))}
const pixelTrees=[];for(let i=0;i<34;i++){let a=rand(0,Math.PI*2),r=rand(2.5,12);pixelTrees.push({obj:tree(Math.cos(a)*r,Math.sin(a)*r,rand(.8,1.3),true),a,r})}
// Small luminous blocks give the corruption a readable voxel silhouette without a post-process dependency.
const blockField=new THREE.Group();scene.add(blockField);for(let i=0;i<120;i++){let a=rand(0,Math.PI*2),r=Math.sqrt(Math.random())*13;let b=mesh(new THREE.BoxGeometry(rand(.18,.65),rand(.18,.8),rand(.18,.65)),i%4?mats.pixel:mats.glow,blockField,[Math.cos(a)*r,rand(.1,2.8),Math.sin(a)*r]);b.rotation.set(rand(0,6),rand(0,6),rand(0,6));b.userData.seed=Math.random()*6}
// Circle boundary + subtle grid lines are the zone's visual indicator hooks.
const zoneRing=new THREE.Mesh(new THREE.TorusGeometry(1,.095,6,128),new THREE.MeshBasicMaterial({color:'#f4bb77',transparent:true,opacity:.92}));zoneRing.rotation.x=Math.PI/2;zoneRing.position.y=.12;scene.add(zoneRing);
const zoneHalo=new THREE.Mesh(new THREE.CircleGeometry(1,64),new THREE.MeshBasicMaterial({color:'#f1a466',transparent:true,opacity:.07,side:THREE.DoubleSide,depthWrite:false}));zoneHalo.rotation.x=-Math.PI/2;zoneHalo.position.y=.035;scene.add(zoneHalo);
const grid=new THREE.GridHelper(40,40,'#8de6da','#62b9ac');grid.position.y=.06;grid.material.transparent=true;grid.material.opacity=.17;scene.add(grid);

// Hero silhouette is assembled from primitives so this project runs without external model assets.
const hero=new THREE.Group();scene.add(hero);const torso=mesh(new THREE.CapsuleGeometry(.39,.66,5,8),mats.cloth,hero,[0,1.16,0]);const head=mesh(new THREE.SphereGeometry(.27,12,10),mats.skin,hero,[0,1.9,-.02]);const hood=mesh(new THREE.SphereGeometry(.29,10,8,0,Math.PI*2,0,Math.PI*.56),mats.cloth,hero,[0,2.02,-.015]);
const cape=mesh(new THREE.BoxGeometry(.66,.88,.13),new THREE.MeshStandardMaterial({color:'#263d36',roughness:1,side:THREE.DoubleSide}),hero,[0,1.05,.31]);cape.rotation.x=-.1;
const armL=new THREE.Group();armL.position.set(-.42,1.46,0);hero.add(armL);mesh(new THREE.CapsuleGeometry(.12,.48,4,6),mats.cloth,armL,[0,-.27,0]);const armR=new THREE.Group();armR.position.set(.4,1.48,0);hero.add(armR);mesh(new THREE.CapsuleGeometry(.12,.48,4,6),mats.cloth,armR,[0,-.27,0]);
const swordModel=new THREE.Group();hero.add(swordModel);mesh(new THREE.BoxGeometry(.08,.82,.1),mats.steel,swordModel,[0,.15,0]);mesh(new THREE.BoxGeometry(.34,.08,.14),mats.gold,swordModel,[0,-.27,0]);mesh(new THREE.CylinderGeometry(.045,.055,.32,7),mats.bark,swordModel,[0,-.47,0]);swordModel.position.set(.53,1.15,-.15);swordModel.rotation.z=-.42;
const spearModel=new THREE.Group();hero.add(spearModel);mesh(new THREE.CylinderGeometry(.035,.045,2.2,7),mats.bark,spearModel,[0,0,0]);mesh(new THREE.ConeGeometry(.12,.48,6),mats.steel,spearModel,[0,1.3,0]);spearModel.position.set(.52,1.1,-.28);spearModel.rotation.x=-.12;spearModel.visible=false;
const shieldModel=new THREE.Group();hero.add(shieldModel);mesh(new THREE.BoxGeometry(.58,.78,.13),mats.gold,shieldModel,[0,0,0]);mesh(new THREE.BoxGeometry(.43,.62,.08),mats.cloth,shieldModel,[0,0,-.08]);mesh(new THREE.OctahedronGeometry(.12),mats.glow,shieldModel,[0,0,-.14]);shieldModel.position.set(-.56,1.12,-.2);shieldModel.visible=false;
const player={pos:hero.position,health:100,stamina:100,weapon:'sword',facing:new THREE.Vector3(0,0,-1),attackCd:0,attackTime:0,invuln:0,parry:0,blocking:false,dodge:0};

// Active state machine: spreading -> seeded OR purifying -> purified.
const ZoneState=Object.freeze({SPREADING:'SPREADING',PURIFYING:'PURIFYING',SEEDED:'SEEDED',PURIFIED:'PURIFIED'});
class InfectionZone{
 constructor(){this.state=ZoneState.SPREADING;this.radius=11.2;this.maxRadius=17;this.spreadRate=.13;this.isSpreading=true;this.age=0;this.purifyProgress=0;this.seededAt=0;this.monsters=[];this.animals=[];this.shards=[];this.mutationClock=0;this.stableSpawn=0;this.updateVisuals()}
 transition(next){if(this.state===next)return;this.state=next;if(next===ZoneState.SEEDED){this.isSpreading=false;this.seededAt=performance.now()/1000;this.stableSpawn=0;this.spawnShards(7);this.visualToast('A PIXEL SANCTUARY','The spread is sealed. The strange growth remains.')}if(next===ZoneState.PURIFYING){this.isSpreading=false;this.purifyProgress=0;this.visualToast('PURIFICATION BEGUN','The forest is reclaiming the wound.')}if(next===ZoneState.PURIFIED){this.radius=0;this.visualToast('THE FOREST REMEMBERS','The pixel wound has been healed.')}this.updateVisuals()}
 update(dt){this.age+=dt;if(this.isSpreading){this.radius=Math.min(this.maxRadius,this.radius+this.spreadRate*dt);this.mutationClock+=dt;if(this.mutationClock>9){this.mutationClock=0;this.mutateAnimals()}}if(this.state===ZoneState.PURIFYING){this.purifyProgress+=dt;this.radius=Math.max(0,this.radius-dt*2.35);if(this.purifyProgress>4.8||this.radius<.15)this.transition(ZoneState.PURIFIED)}if(this.state===ZoneState.SEEDED){this.stableSpawn+=dt;if(this.stableSpawn>25){this.stableSpawn=0;if(this.monsters.length<2)this.spawnMonster(rand(-8,8),rand(-8,8),'stalker');this.spawnShards(3)}}this.monsters=this.monsters.filter(m=>m.alive);this.updateVisuals()}
 updateVisuals(){zoneRing.scale.setScalar(Math.max(.001,this.radius));zoneHalo.scale.setScalar(Math.max(.001,this.radius));grid.scale.set(this.radius/20,1,this.radius/20);zoneRing.visible=this.state!==ZoneState.PURIFIED;zoneHalo.visible=zoneRing.visible;grid.visible=zoneRing.visible;zoneRing.material.color.set(this.state===ZoneState.SEEDED?'#75e7ed':this.state===ZoneState.PURIFYING?'#baff75':'#f4bb77');zoneHalo.material.color.set(this.state===ZoneState.SEEDED?'#69e7ee':this.state===ZoneState.PURIFYING?'#baff75':'#f1a466');zoneRing.material.opacity=this.state===ZoneState.PURIFYING?.4:.9;for(const t of pixelTrees)t.obj.visible=t.r<this.radius+1;blockField.visible=this.state!==ZoneState.PURIFIED;}
 contains(x,z){return Math.hypot(x,z)<=this.radius}
 mutateAnimals(){for(const animal of this.animals){if(animal.alive&&this.contains(animal.group.position.x,animal.group.position.z)){animal.alive=false;animal.group.visible=false;this.spawnMonster(animal.group.position.x,animal.group.position.z,animal.kind==='stag'?'brute':'stalker')}}}
 spawnMonster(x,z,type='stalker'){const g=makeMonster(type);g.position.set(x,0,z);scene.add(g);this.monsters.push({group:g,type,hp:type==='brute'?70:45,maxHp:type==='brute'?70:45,alive:true,attack:rand(1,2),phase:rand(0,6),hitFlash:0})}
 spawnShards(n){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),r=rand(2,Math.max(3,this.radius-1));const g=new THREE.Group();g.position.set(Math.cos(a)*r,0,Math.sin(a)*r);scene.add(g);mesh(new THREE.OctahedronGeometry(.22,0),new THREE.MeshStandardMaterial({color:'#a4fff1',emissive:'#49d9ca',emissiveIntensity:1.6,metalness:.3,roughness:.2}),g,[0,.38,0]);const ring=mesh(new THREE.TorusGeometry(.35,.018,4,16),new THREE.MeshBasicMaterial({color:'#79e6eb',transparent:true,opacity:.7}),g,[0,.04,0]);ring.rotation.x=Math.PI/2;this.shards.push({group:g,alive:true,phase:rand(0,6)})}}
}
function makeMonster(type){const g=new THREE.Group();const brute=type==='brute';const size=brute?1.27:1;g.scale.setScalar(size);mesh(new THREE.SphereGeometry(.62,9,7),mats.monster,g,[0,.86,0]);mesh(new THREE.BoxGeometry(.58,.7,.5),mats.pixel,g,[0,1.22,-.03]);for(const x of [-.3,.3]){mesh(new THREE.ConeGeometry(.12,.44,5),mats.glow,g,[x,1.73,-.03]);mesh(new THREE.SphereGeometry(.085,8,6),new THREE.MeshBasicMaterial({color:'#d7ff9a'}),g,[x,.97,-.55]);const leg=mesh(new THREE.CapsuleGeometry(.13,.48,3,5),mats.monster,g,[x*.75,.25,.02]);leg.rotation.z=x*.25}for(let i=0;i<3;i++){const cube=mesh(new THREE.BoxGeometry(.25,.25,.25),mats.pixel,g,[rand(-.7,.7),rand(.25,1.5),rand(-.5,.5)]);cube.rotation.set(rand(0,2),rand(0,2),rand(0,2))}g.userData.type=type;return g;}
const zone=new InfectionZone();zone.spawnMonster(-3.1,-2.5,'stalker');zone.spawnMonster(3.2,-4,'brute');
// Wildlife is deliberately visible in the mixed organic/pixel border and can be rescued or lost to mutation.
function makeAnimal(kind,x,z){const g=new THREE.Group();mesh(new THREE.CapsuleGeometry(.22,.62,4,6),mats.animal,g,[0,.68,0]).rotation.z=Math.PI/2;mesh(new THREE.SphereGeometry(.25,9,7),mats.animal,g,[.38,.9,-.02]);for(const sx of [-.13,.14])for(const sz of [-.2,.2])mesh(new THREE.CylinderGeometry(.05,.07,.45,5),mats.animal,g,[sx,.25,sz]);if(kind==='stag'){for(const sx of [-.12,.12]){const ant=mesh(new THREE.CylinderGeometry(.025,.045,.58,5),mats.gold,g,[.42,1.35,sx]);ant.rotation.z=-.35;mesh(new THREE.ConeGeometry(.06,.2,5),mats.gold,g,[.49,1.66,sx])}}scene.add(g);return{group:g,kind,alive:true,phase:rand(0,6),homeX:x,homeZ:z}}
zone.animals.push(makeAnimal('stag',-7,7),makeAnimal('hare',8,6),makeAnimal('hare',-10,-3));

const keys=new Set();let mouseDown=false,mouseRight=false,elapsed=0,toastTimer=0,shardsCollected=0,seeds=1;let cameraYaw=0;const lookTarget=new THREE.Vector3();
function setWeapon(which){player.weapon=which;swordModel.visible=which==='sword';spearModel.visible=which==='spear';shieldModel.visible=which==='shield';document.querySelectorAll('.weapon-slot').forEach(b=>b.classList.toggle('active',b.dataset.weapon===which));const names={sword:'ASHEN SWORD',spear:'MARCH SPEAR',shield:'BULWARK SHIELD'};document.querySelector('#weapon-label').textContent=names[which];document.querySelector('#weapon-caption').textContent=names[which]}
function visualToast(title,sub){const el=document.querySelector('#toast');el.querySelector('b').textContent=title;el.querySelector('small').textContent=sub;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3600)}
function prompt(text){const el=document.querySelector('#prompt');el.textContent=text;el.classList.toggle('visible',!!text)}
function doAttack(){if(player.attackCd>0||player.stamina<8)return;player.attackCd=player.weapon==='spear'?.52:.43;player.attackTime=.3;player.stamina-=player.weapon==='shield'?6:9;const reach=player.weapon==='spear'?5.2:player.weapon==='shield'?2.2:3.1;const damage=player.weapon==='spear'?26:player.weapon==='shield'?16:34;let hits=0;for(const m of zone.monsters){if(!m.alive)continue;const dx=m.group.position.x-player.pos.x,dz=m.group.position.z-player.pos.z,d=Math.hypot(dx,dz),dot=(dx*player.facing.x+dz*player.facing.z)/(d||1);if(d<reach&&dot>-.05){m.hp-=damage;hits++;m.hitFlash=.2;const push=Math.max(.1,d);m.group.position.x+=dx/d*.55;m.group.position.z+=dz/d*.55;if(m.hp<=0){m.alive=false;scene.remove(m.group);zone.spawnShards(m.type==='brute'?3:2);shardsCollected+=0;visualToast('PIXEL BEAST DISMANTLED',m.type==='brute'?'Heavy fragments scattered nearby.':'Digital shards scattered nearby.')}}}if(hits===0)document.querySelector('#combat-flash').classList.add('on');}
function tryPurify(){if(zone.state!==ZoneState.SPREADING||!zone.contains(player.pos.x,player.pos.z)||Math.hypot(player.pos.x,player.pos.z)>zone.radius-1){visualToast('MOVE TO THE WOUND','Stand inside the pixel border to act.');return}if(zone.monsters.some(m=>m.alive)){visualToast('THE WOUND IS GUARDED','Defeat every Pixel Monster before purifying.');return}zone.transition(ZoneState.PURIFYING)}
function plantSeed(){if(zone.state!==ZoneState.SPREADING||!zone.contains(player.pos.x,player.pos.z)){visualToast('NO PURCHASE HERE','Stand inside an active pixel zone to plant a seed.');return}if(seeds<1){visualToast('SEED POCKET EMPTY','Find another Pixel Seed in the old ruins.');return}seeds--;zone.transition(ZoneState.SEEDED)}
function harvest(){let nearest=null,dist=2.8;for(const s of zone.shards){if(!s.alive)continue;const d=s.group.position.distanceTo(player.pos);if(d<dist){dist=d;nearest=s}}if(nearest){nearest.alive=false;scene.remove(nearest.group);shardsCollected++;document.querySelector('#shard-count').textContent=String(shardsCollected).padStart(2,'0');visualToast('SHARD RECOVERED','Digital matter · useful for weapon crafting.')}else visualToast('NOTHING IN REACH','Move close to a floating pixel shard.')}
function dodge(){if(player.stamina<18||player.dodge>0)return;player.stamina-=18;player.dodge=.3;player.invuln=.45;player.pos.x+=player.facing.x*1.7;player.pos.z+=player.facing.z*1.7}
function setParry(){player.parry=.68;player.blocking=true;setTimeout(()=>player.blocking=false,650)}
function onKey(e,down){const k=e.key.toLowerCase();if(down)keys.add(k);else keys.delete(k);if(!down)return;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='1')setWeapon('sword');if(k==='2')setWeapon('spear');if(k==='3')setWeapon('shield');if(k===' '||k==='j')doAttack();if(k==='q')setParry();if(k==='e')tryPurify();if(k==='f')plantSeed();if(k==='r')harvest();if(k==='shift')dodge()}
window.addEventListener('keydown',e=>onKey(e,true));window.addEventListener('keyup',e=>onKey(e,false));
canvas.addEventListener('mousedown',e=>{if(e.button===0)doAttack();if(e.button===2){mouseRight=true;player.blocking=true}});window.addEventListener('mouseup',e=>{if(e.button===2){mouseRight=false;player.blocking=false}});canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('mousemove',e=>{if(e.buttons===4)cameraYaw-=e.movementX*.004});
document.querySelectorAll('.weapon-slot').forEach(b=>b.addEventListener('click',()=>setWeapon(b.dataset.weapon)));document.querySelector('#guide-toggle').onclick=()=>document.querySelector('#guide-card').classList.toggle('open');document.querySelector('#close-guide').onclick=()=>document.querySelector('#guide-card').classList.remove('open');
let touchVec={};document.querySelectorAll('[data-move]').forEach(b=>{const val=b.dataset.move;b.addEventListener('pointerdown',e=>{e.preventDefault();touchVec[val]=true});['pointerup','pointercancel','pointerleave'].forEach(ev=>b.addEventListener(ev,()=>touchVec[val]=false))});document.querySelector('[data-action=attack]').addEventListener('pointerdown',doAttack);document.querySelector('[data-action=dodge]').addEventListener('pointerdown',dodge);document.querySelector('[data-action=interact]').addEventListener('pointerdown',()=>zone.state===ZoneState.SPREADING?tryPurify():harvest());
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});

function damagePlayer(amount,source){if(player.invuln>0)return;if(player.parry>0){source.hp-=30;source.hitFlash=.2;player.parry=0;visualToast('PERFECT PARRY','A clean deflection opens the beast.');return}if(player.blocking&&player.weapon==='shield'){amount*=.18;player.stamina=Math.max(0,player.stamina-amount*.7)}player.health=Math.max(0,player.health-amount);player.invuln=.55;document.querySelector('#combat-flash').classList.add('on');if(player.health<=0){player.health=100;player.pos.set(0,0,15);visualToast('THE FOREST PULLS YOU BACK','You wake at the edge of the clearing.')}}
function updateHUD(){document.querySelector('#health-value').textContent=Math.ceil(player.health);document.querySelector('#health-bar').style.width=player.health+'%';document.querySelector('#stamina-bar').style.width=player.stamina+'%';document.querySelector('#shard-count').textContent=String(shardsCollected).padStart(2,'0');document.querySelector('#seed-count').textContent=String(seeds).padStart(2,'0');document.querySelector('#zone-radius').textContent=zone.radius.toFixed(0)+'m';const alive=zone.monsters.filter(m=>m.alive).length;document.querySelector('#threat-count').textContent=String(alive).padStart(2,'0');const states={SPREADING:['ACTIVE INFECTION','SPREADING · '+alive+' PIXEL BEASTS REMAIN'],PURIFYING:['PURIFICATION','FOREST RECOVERY IN PROGRESS'],SEEDED:['STABILIZED SANCTUARY','STABLE · SPREAD HALTED · FARMING ENABLED'],PURIFIED:['WOUND HEALED','PURIFIED · ORGANIC FOREST RESTORED']};let [name,note]=states[zone.state];document.querySelector('#zone-state').textContent=name;document.querySelector('#zone-note').textContent=note;document.querySelector('#zone-progress').style.width=(zone.radius/zone.maxRadius*100)+'%';document.querySelector('#zone-progress').style.background=zone.state==='SEEDED'?'#75e7ed':zone.state==='PURIFYING'||zone.state==='PURIFIED'?'#baff75':'#f4bd74';document.querySelector('.zone-alert').textContent=zone.state==='SEEDED'?'● LOCKED':zone.state==='PURIFIED'?'✓ CLEAR':'● LIVE';document.querySelector('.zone-alert').style.color=zone.state==='SEEDED'?'#75e7ed':zone.state==='PURIFIED'?'#baff75':'#f3a47d'}
function updatePrompt(){const d=Math.hypot(player.pos.x,player.pos.z);if(zone.state==='SPREADING'&&zone.contains(player.pos.x,player.pos.z)&&zone.monsters.every(m=>!m.alive))prompt('E  ·  PURIFY THE WOUND     /     F  ·  PLANT PIXEL SEED');else if(zone.state==='SPREADING'&&zone.contains(player.pos.x,player.pos.z))prompt('F  ·  PLANT PIXEL SEED  (STABILIZE ZONE)');else if(zone.state==='SEEDED'&&zone.shards.some(s=>s.alive&&s.group.position.distanceTo(player.pos)<3))prompt('R  ·  HARVEST PIXEL SHARD');else if(zone.state==='PURIFIED'&&d<10)prompt('THE MOSSWOUND IS HEALED');else prompt('')}
const clock=new THREE.Clock();function tick(){requestAnimationFrame(tick);const dt=Math.min(clock.getDelta(),.04);elapsed+=dt;zone.update(dt);
 // Character movement is camera-relative; the camera trails rather than snapping, preserving a third-person read.
 const input=new THREE.Vector3((keys.has('d')||keys.has('arrowright')||touchVec.right?1:0)-(keys.has('a')||keys.has('arrowleft')||touchVec.left?1:0),0,(keys.has('s')||keys.has('arrowdown')||touchVec.back?1:0)-(keys.has('w')||keys.has('arrowup')||touchVec.forward?1:0));if(input.lengthSq()>0){input.normalize().applyAxisAngle(new THREE.Vector3(0,1,0),cameraYaw);let speed=player.dodge>0?10:5.1;player.pos.addScaledVector(input,speed*dt);player.facing.copy(input);hero.rotation.y=Math.atan2(player.facing.x,player.facing.z)+Math.PI;}
