 transition(next){if(this.state===next)return;this.state=next;if(next===ZoneState.SEEDED){this.isSpreading=false;this.stableSpawn=0;this.spawnShards(7);this.visualToast('A PIXEL SANCTUARY','The spread is sealed. The strange growth remains.')}if(next===ZoneState.PURIFYING){this.isSpreading=false;this.purifyProgress=0;this.visualToast('PURIFICATION BEGUN','The forest is reclaiming the wound.')}if(next===ZoneState.PURIFIED){this.radius=0;this.visualToast('THE FOREST REMEMBERS','The pixel wound has been healed.')}this.updateVisuals()}
 update(dt){this.age+=dt;if(this.isSpreading){this.radius=Math.min(this.maxRadius,this.radius+this.spreadRate*dt);this.mutationClock+=dt;if(this.mutationClock>9){this.mutationClock=0;this.mutateAnimals()}}if(this.state===ZoneState.PURIFYING){this.purifyProgress+=dt;this.radius=Math.max(0,this.radius-dt*2.35);if(this.purifyProgress>4.8||this.radius<.15)this.transition(ZoneState.PURIFIED)}if(this.state===ZoneState.SEEDED){this.stableSpawn+=dt;if(this.stableSpawn>25){this.stableSpawn=0;if(this.monsters.filter(m=>m.alive).length<2)this.spawnMonster(rand(-8,8),rand(-8,8),'stalker');this.spawnShards(3)}}this.monsters=this.monsters.filter(m=>m.alive);this.updateVisuals()}
 updateVisuals(){zoneRing.scale.setScalar(Math.max(.001,this.radius));zoneHalo.scale.setScalar(Math.max(.001,this.radius));grid.scale.set(this.radius/20,1,this.radius/20);zoneRing.visible=this.state!==ZoneState.PURIFIED;zoneHalo.visible=zoneRing.visible;grid.visible=zoneRing.visible;zoneRing.material.color.set(this.state===ZoneState.SEEDED?'#75e7ed':this.state===ZoneState.PURIFYING?'#baff75':'#f4bb77');zoneHalo.material.color.set(this.state===ZoneState.SEEDED?'#69e7ee':this.state===ZoneState.PURIFYING?'#baff75':'#f1a466');zoneRing.material.opacity=this.state===ZoneState.PURIFYING?.4:.9;for(const t of pixelTrees)t.obj.visible=t.r<this.radius+1;blockField.visible=this.state!==ZoneState.PURIFIED}
 contains(x,z){return Math.hypot(x,z)<=this.radius}
