 spawnShards(n){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),r=rand(2,Math.max(3,this.radius-1));const g=new THREE.Group();g.position.set(Math.cos(a)*r,0,Math.sin(a)*r);scene.add(g);mesh(new THREE.OctahedronGeometry(.22,0),new THREE.MeshStandardMaterial({color:'#a4fff1',emissive:'#49d9ca',emissiveIntensity:1.6,metalness:.3,roughness:.2}),g,[0,.38,0]);const ring=mesh(new THREE.TorusGeometry(.35,.018,4,16),new THREE.MeshBasicMaterial({color:'#79e6eb',transparent:true,opacity:.7}),g,[0,.04,0]);ring.rotation.x=Math.PI/2;this.shards.push({group:g,alive:true,phase:rand(0,6)})}
 visualToast(title,sub){visualToast(title,sub)}}
