const zone=new InfectionZone();zone.spawnMonster(-3.1,-2.5,'stalker');zone.spawnMonster(3.2,-4,'brute');zone.animals.push(makeAnimal('stag',-7,7),makeAnimal('hare',8,6),makeAnimal('hare',-10,-3));

let shardsCollected=0,seeds=1,elapsed=0,toastTimer=0,cameraYaw=0;const keys=new Set(),touchVec={};
function visualToast(title,sub){const el=document.querySelector('#toast');el.querySelector('b').textContent=title;el.querySelector('small').textContent=sub;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3400)}
function setWeapon(which){player.weapon=which;swordModel.visible=which==='sword';spearModel.visible=which==='spear';shieldModel.visible=which==='shield';document.querySelectorAll('.weapon-slot').forEach(b=>b.classList.toggle('active',b.dataset.weapon===which));const names={sword:'ASHEN SWORD',spear:'MARCH SPEAR',shield:'BULWARK SHIELD'};document.querySelector('#weapon-label').textContent=names[which];document.querySelector('#weapon-caption').textContent=names[which]}
function prompt(text){const el=document.querySelector('#prompt');el.textContent=text;el.classList.toggle('visible',!!text)}
function doAttack(){if(player.attackCd>0||player.stamina<8)return;player.attackCd=player.weapon==='spear'?.56:.43;player.attackTime=.3;player.stamina-=player.weapon==='shield'?6:9;const reach=player.weapon==='spear'?5.2:player.weapon==='shield'?2.4:3.25,damage=player.weapon==='spear'?26:player.weapon==='shield'?16:34;let hits=0;for(const m of zone.monsters){if(!m.alive)continue;const dx=m.group.position.x-player.pos.x,dz=m.group.position.z-player.pos.z,d=Math.hypot(dx,dz),dot=(dx*player.facing.x+dz*player.facing.z)/(d||1);if(d<reach&&dot>-.15){m.hp-=damage;hits++;m.hitFlash=.2;const push=Math.max(.1,d);m.group.position.x+=dx/push*.5;m.group.position.z+=dz/push*.5;if(m.hp<=0){m.alive=false;scene.remove(m.group);zone.spawnShards(m.type==='brute'?4:2);visualToast('PIXEL BEAST DISMANTLED',m.type==='brute'?'Heavy fragments scattered nearby.':'Digital shards scattered nearby.')}}}if(!hits){const f=document.querySelector('#combat-flash');f.classList.add('on');setTimeout(()=>f.classList.remove('on'),180)}}
function tryPurify(){if(zone.state!==ZoneState.SPREADING||!zone.contains(player.pos.x,player.pos.z)){visualToast('MOVE TO THE WOUND','Stand inside the pixel border to act.');return}if(zone.monsters.some(m=>m.alive)){visualToast('THE WOUND IS GUARDED','Defeat every Pixel Monster before purifying.');return}zone.transition(ZoneState.PURIFYING)}
function plantSeed(){if(zone.state!==ZoneState.SPREADING||!zone.contains(player.pos.x,player.pos.z)){visualToast('NO PURCHASE HERE','Stand inside an active pixel zone to plant a seed.');return}if(seeds<1){visualToast('SEED POCKET EMPTY','Find another Pixel Seed in the old ruins.');return}seeds--;zone.transition(ZoneState.SEEDED)}
function harvest(){let nearest=null,dist=2.8;for(const s of zone.shards){if(!s.alive)continue;const d=s.group.position.distanceTo(player.pos);if(d<dist){dist=d;nearest=s}}if(nearest){nearest.alive=false;scene.remove(nearest.group);shardsCollected++;visualToast('SHARD RECOVERED','Digital matter · useful for weapon crafting.')}else visualToast('NOTHING IN REACH','Move close to a floating pixel shard.')}
function dodge(){if(player.stamina<18||player.dodge>0)return;player.stamina-=18;player.dodge=.3;player.invuln=.45;player.pos.x+=player.facing.x*1.7;player.pos.z+=player.facing.z*1.7}
function setParry(){player.parry=.68;player.blocking=true;setTimeout(()=>{if(player.parry<=0)player.blocking=false},680)}
function onKey(e,down){const k=e.key.toLowerCase();if(down)keys.add(k);else keys.delete(k);if(!down)return;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='1')setWeapon('sword');if(k==='2')setWeapon('spear');if(k==='3')setWeapon('shield');if(k===' '||k==='j')doAttack();if(k==='q')setParry();if(k==='e')tryPurify();if(k==='f')plantSeed();if(k==='r')harvest();if(k==='shift')dodge()}
window.addEventListener('keydown',e=>onKey(e,true));window.addEventListener('keyup',e=>onKey(e,false));canvas.addEventListener('mousedown',e=>{if(e.button===0)doAttack();if(e.button===2){player.blocking=true}});window.addEventListener('mouseup',e=>{if(e.button===2)player.blocking=false});canvas.addEventListener('contextmenu',e=>e.preventDefault());
document.querySelectorAll('.weapon-slot').forEach(b=>b.addEventListener('click',()=>setWeapon(b.dataset.weapon)));document.querySelector('#guide-toggle').onclick=()=>document.querySelector('#guide-card').classList.toggle('open');document.querySelector('#close-guide').onclick=()=>document.querySelector('#guide-card').classList.remove('open');
document.querySelectorAll('[data-move]').forEach(b=>{const val=b.dataset.move;b.addEventListener('pointerdown',e=>{e.preventDefault();touchVec[val]=true});['pointerup','pointercancel','pointerleave'].forEach(ev=>b.addEventListener(ev,()=>touchVec[val]=false))});document.querySelector('[data-action=attack]').addEventListener('pointerdown',doAttack);document.querySelector('[data-action=dodge]').addEventListener('pointerdown',dodge);document.querySelector('[data-action=interact]').addEventListener('pointerdown',()=>zone.state===ZoneState.SPREADING?tryPurify():harvest());
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});

