let comboStep=0,comboWindow=0,gameTime=0,lastTime=performance.now();
function updatePlayer(dt){
  player.attackCd=Math.max(0,player.attackCd-dt);player.attackTime=Math.max(0,player.attackTime-dt);player.invuln=Math.max(0,player.invuln-dt);player.dodge=Math.max(0,player.dodge-dt);player.parry=Math.max(0,player.parry-dt);comboWindow=Math.max(0,comboWindow-dt);
  if(player.parry===0&&player.weapon!=='shield'&&!keys.has('mouse2'))player.blocking=false;
  const forward=(keys.has('w')||keys.has('arrowup')||touchVec.forward?1:0)-(keys.has('s')||keys.has('arrowdown')||touchVec.back?1:0);
  const side=(keys.has('d')||keys.has('arrowright')||touchVec.right?1:0)-(keys.has('a')||keys.has('arrowleft')||touchVec.left?1:0);
  const moving=forward!==0||side!==0;
  if(moving){const len=Math.hypot(forward,side)||1;const fwd=new THREE.Vector3(-Math.sin(cameraYaw),0,-Math.cos(cameraYaw));const right=new THREE.Vector3(Math.cos(cameraYaw),0,-Math.sin(cameraYaw));const dir=fwd.multiplyScalar(forward/len).add(right.multiplyScalar(side/len)).normalize();player.facing.lerp(dir,Math.min(1,dt*12)).normalize();const speed=player.dodge>0?13:player.blocking?2.3:5.2;player.pos.addScaledVector(dir,speed*dt);player.pos.x=clamp(player.pos.x,-55,55);player.pos.z=clamp(player.pos.z,-55,55);hero.rotation.y=Math.atan2(-player.facing.x,-player.facing.z)}
  player.stamina=Math.min(100,player.stamina+dt*(player.blocking?4:15));hero.position.y=player.dodge>0?Math.sin((.3-player.dodge)/.3*Math.PI)*.12:0;
  const swing=player.attackTime>0?Math.sin((.3-player.attackTime)/.3*Math.PI):0;swordModel.rotation.z=-.42-swing*1.65;spearModel.rotation.x=-.12-swing*.9;shieldModel.rotation.z=player.blocking?-.45:0;armR.rotation.x=player.attackTime>0?-swing*.8:0;
  hero.position.y+=moving&&player.dodge<=0?Math.sin(gameTime*11)*.035:0;
}
function hurtPlayer(amount,source){if(player.invuln>0)return;if(player.parry>0){player.parry=0;player.blocking=false;source.attack=1.1;source.stun=.85;visualToast('PERFECT PARRY','The beast is staggered. Strike now.');return}if(player.blocking&&player.weapon==='shield'){amount*=.16;player.stamina=Math.max(0,player.stamina-amount*1.3);if(player.stamina<=0)player.blocking=false;visualToast('SHIELD BLOCK','Most damage absorbed.')}else if(player.blocking){amount*=.48;player.stamina=Math.max(0,player.stamina-amount)}player.health=Math.max(0,player.health-amount);player.invuln=.65;if(player.health===0){player.health=100;player.stamina=65;player.pos.set(0,0,15);visualToast('THE FOREST CATCHES YOU','You awaken at the trailhead. Keep going.')}}
function updateMonsters(dt){for(const m of zone.monsters){if(!m.alive)continue;m.attack-=dt;m.hitFlash=Math.max(0,m.hitFlash-dt);m.stun=Math.max(0,(m.stun||0)-dt);const g=m.group,dx=player.pos.x-g.position.x,dz=player.pos.z-g.position.z,d=Math.hypot(dx,dz);if(m.stun>0)continue;if(d<14){if(d>1.55){const speed=m.type==='brute'?1.65:m.type==='skitter'?3.35:2.25;g.position.x+=dx/(d||1)*speed*dt;g.position.z+=dz/(d||1)*speed*dt;g.rotation.y=Math.atan2(-dx,-dz)}else if(m.attack<=0){m.attack=m.type==='skitter'?1.35:m.type==='brute'?2.15:1.75;m.windup=.42;m.target={x:player.pos.x,z:player.pos.z}}if(m.windup>0){m.windup-=dt;if(m.windup<=0&&d<2.35){const vx=player.pos.x-g.position.x,vz=player.pos.z-g.position.z,front=(vx*player.facing.x+vz*player.facing.z)/(Math.hypot(vx,vz)||1)>-.3;if(front)hurtPlayer(m.type==='brute'?23:m.type==='skitter'?9:14,m);else if(player.weapon==='shield'&&player.blocking)hurtPlayer(14,m)}}}
    g.position.y=Math.sin(gameTime*3+m.phase)*.055;for(const child of g.children){if(child.material===mats.monster){child.material.emissiveIntensity=m.hitFlash>0?2.3:.55}}
  }}
function updateAnimals(dt){for(const a of zone.animals){if(!a.alive)continue;a.phase+=dt;const threat=zone.contains(a.group.position.x,a.group.position.z);if(threat){const dx=a.group.position.x,dz=a.group.position.z,d=Math.hypot(dx,dz)||1;a.group.position.x+=dx/d*dt*.55;a.group.position.z+=dz/d*dt*.55}else{a.group.position.x=a.homeX+Math.sin(a.phase*.42)*.65;a.group.position.z=a.homeZ+Math.cos(a.phase*.35)*.5}a.group.rotation.y=Math.sin(a.phase*.6)*.18}}
function updateCamera(dt){const target=new THREE.Vector3(player.pos.x,player.pos.y+1.15,player.pos.z);const desired=new THREE.Vector3(player.pos.x+Math.sin(cameraYaw)*10,player.pos.y+6.6,player.pos.z+Math.cos(cameraYaw)*10);camera.position.lerp(desired,1-Math.exp(-dt*4.5));camera.lookAt(target)}
function updateHud(dt){const pct=player.health;document.querySelector('#health-value').textContent=Math.ceil(pct);document.querySelector('#health-bar').style.width=`${pct}%`;document.querySelector('#stamina-bar').style.width=`${player.stamina}%`;document.querySelector('#shard-count').textContent=String(shardsCollected).padStart(2,'0');document.querySelector('#seed-count').textContent=String(seeds).padStart(2,'0');document.querySelector('#zone-radius').textContent=`${Math.round(zone.radius)}m`;const alive=zone.monsters.filter(m=>m.alive).length;document.querySelector('#threat-count').textContent=String(alive).padStart(2,'0');document.querySelector('#zone-state').textContent=zone.state==='SPREADING'?'ACTIVE INFECTION':zone.state==='PURIFYING'?'PURIFICATION':zone.state==='SEEDED'?'STABLE SANCTUARY':'HEALED FOREST';document.querySelector('.zone-alert').textContent=zone.state==='SPREADING'?'● LIVE':zone.state==='SEEDED'?'◆ STABLE':'● QUIET';document.querySelector('.zone-alert').style.color=zone.state==='SEEDED'?'#68e8ef':zone.state==='PURIFIED'?'#bdff75':'';const progress=zone.state==='PURIFYING'?zone.purifyProgress/4.8:zone.state==='PURIFIED'?1:zone.radius/zone.maxRadius;document.querySelector('#zone-progress').style.width=`${clamp(progress*100,0,100)}%`;document.querySelector('#zone-note').textContent=zone.state==='SPREADING'?`${zone.isSpreading?'SPREADING':'CONTAINED'} · ${alive} PIXEL BEAST${alive===1?'':'S'} REMAIN`:zone.state==='PURIFYING'?`RECLAIMING · ${Math.max(0,Math.ceil(4.8-zone.purifyProgress))} SECONDS`:zone.state==='SEEDED'?'STABLE · SANCTUARY RETAINS ITS STRANGE GROWTH':'PURIFIED · ORGANIC LIFE RETURNS';
  const inside=zone.contains(player.pos.x,player.pos.z),nearest=zone.shards.some(s=>s.alive&&s.group.position.distanceTo(player.pos)<2.8);let msg='';if(nearest)msg='R · HARVEST PIXEL SHARD';else if(inside&&zone.state==='SPREADING'&&alive===0)msg='E · PURIFY  /  F · PLANT PIXEL SEED';else if(inside&&zone.state==='SPREADING')msg=`DEFEAT ${alive} PIXEL BEAST${alive===1?'':'S'} TO CHOOSE`;prompt(msg);
  const label=document.querySelector('.zone-label');label.style.opacity=zone.state==='PURIFIED'?'0':'.9';}
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.04,(now-lastTime)/1000);lastTime=now;gameTime+=dt;zone.update(dt);updatePlayer(dt);updateMonsters(dt);updateAnimals(dt);updateCamera(dt);for(const s of zone.shards)if(s.alive){s.phase+=dt;s.group.children[0].position.y=.38+Math.sin(s.phase*2)*.12;s.group.rotation.y=s.phase*.8}for(const b of blockField.children){b.rotation.y+=dt*.15;b.position.y+=Math.sin(gameTime*1.4+b.userData.seed)*dt*.12}updateHud(dt);renderer.render(scene,camera)}
